{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, the closest retrieved analogue (Morgan 0.28), has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; it shares the N-prenyl tertiary amine and fused lipophilic ring system with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "8-Prenylnaringenin shows low oral bioavailability in humans, supporting that prenylation can be associated with poor oral exposure, though this polyphenol is less drug-like than the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "MK-458, a small basic fused-ring drug with a tertiary amine, has an absolute oral bioavailability of about 5% in patients, supporting low F for similar lipophilic basic amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Doravirine has an absolute oral bioavailability of about 64%, providing contradictory high-F evidence, but it is structurally distant and lacks the prenyl group and basic tertiary amine of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Balovaptan is reported with 100% oral bioavailability, contradictory high-F evidence, but it is a BCS class I-like molecule with little structural overlap with the query's prenyl-thione scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low because the most transferable evidence, pentazocine, shows absolute oral bioavailability of 18% in healthy subjects and shares the N-prenyl tertiary amine and fused lipophilic ring system; additional prenylated and basic fused-ring analogues also show low F. High-F comparators are structurally more distant and lack the prenyl group, so they do not override the low-F evidence.",
  "evidence_gaps": [
    "No direct human bioavailability data for the exact benzimidazole-2-thione/N-prenyl scaffold.",
    "The closest analogue pentazocine has a phenolic OH that may increase first-pass metabolism relative to the query's thione.",
    "High-F comparators have different metabolic and physicochemical features, limiting their transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

